<?phpsession_start();require_once "includes/dbconn.php";require_once "functions.php";require_once "includes/basic_includes.php"; // only if this file does NOT print anything!// Check loginif (!isloggedin()) {    header("Location: login.php");    exit;}if (!isset($_GET['id']) || !is_numeric($_GET['id'])) {    die("Invalid Profile ID");}$id = (int)$_GET['id'];$profileid = $id;/* -----------------------------   1. Fetch User Details-------------------------------- */$stmt = $conn->prepare("SELECT * FROM users WHERE id = ?");$stmt->bind_param("i", $id);$stmt->execute();$row3 = $stmt->get_result()->fetch_assoc();$stmt->close();if (!$row3) {    die("User not found");}/* -----------------------------   2. Fetch Customer Details-------------------------------- */$stmt = $conn->prepare("SELECT * FROM customer WHERE cust_id = ?");$stmt->bind_param("i", $id);$stmt->execute();$row = $stmt->get_result()->fetch_assoc();$stmt->close();if (!$row) {    echo "<script>alert('Invalid Profile ID');</script>";    exit;}/* -----------------------------   3. Profile Visit Count-------------------------------- */$session_visit_id = $_SESSION['id'];$stmt = $conn->prepare("SELECT visit FROM profile_visit WHERE ID = ?");$stmt->bind_param("i", $session_visit_id);$stmt->execute();$row_visit = $stmt->get_result()->fetch_assoc();$stmt->close();if ($row_visit && $session_visit_id != $id) {    $new_visit_count = $row_visit['visit'] + 1;    $stmt = $conn->prepare("UPDATE profile_visit SET visit = ? WHERE ID = ?");    $stmt->bind_param("ii", $new_visit_count, $session_visit_id);    $stmt->execute();    $stmt->close();}/* -----------------------------   4. Assign Customer Data-------------------------------- */$fname            = $row['firstname'];$lname            = $row['lastname'];$sex              = $row['sex'];$email            = $row['email'];$dob              = $row['dateofbirth'];$religion         = $row['religion'];$caste            = $row['caste'];$subcaste         = $row['subcaste'];$country          = $row['country'];$state            = $row['state'];$district         = $row['district'];$maritalstatus    = $row['maritalstatus'];$profileby        = $row['profilecreatedby'];$education        = $row['education'];$edudescr         = $row['education_sub'];$bodytype         = $row['body_type'];$physicalstatus   = $row['physical_status'];$drink            = $row['drink'];$smoke            = $row['smoke'];$mothertounge     = $row['mothertounge'];$bloodgroup       = $row['blood_group'];$weight           = $row['weight'];$height           = $row['height'];$colour           = $row['colour'];$diet             = $row['diet'];$occupation       = $row['occupation'];$occupationdescr  = $row['occupation_descr'];$fatheroccupation = $row['fathers_occupation'];$motheroccupation = $row['mothers_occupation'];$income           = $row['annual_income'];$bros             = $row['no_bro'];$sis              = $row['no_sis'];$aboutme          = $row['aboutme'];$mobno            = $row['mobno'];$membership_status = $row['membership'];$age = date("Y") - date("Y", strtotime($dob));/* -----------------------------   5. Fetch Photo-------------------------------- */$stmt = $conn->prepare("SELECT * FROM photos WHERE cust_id = ?");$stmt->bind_param("i", $profileid);$stmt->execute();$row2 = $stmt->get_result()->fetch_assoc();$stmt->close();if (!$row2 || empty($row2['pic1'])) {    $pic1 = ($row3['gender'] === "Male") ? "img/male.png" : "img/female.png";} else {    $pic1 = "profile/" . $profileid . "/" . $row2['pic1'];}?><!DOCTYPE html><html lang="zxx"><head>  <meta charset="utf-8">  <title>Sagun Matrimonial</title>  <!-- mobile responsive meta -->  <meta name="viewport" content="width=device-width, initial-scale=1">  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1">    <!-- ** Plugins Needed for the Project *