prepare("SELECT * FROM customer WHERE profilestat = 1 AND sex = 'Female' ORDER BY profilecreationdate DESC");} else {    $stmt = $conn->prepare("SELECT * FROM customer WHERE profilestat = 1 AND sex = 'Male' ORDER BY profilecreationdate DESC");}$stmt->execute();$result = $stmt->get_result();/* --------------------------------------------------   3. Loop profiles (max 8)-------------------------------------------------- */$count = 1;$count2 = 1;while ($row = $result->fetch_assoc()) {    $profid = $row['cust_id'];    /* --------------------------------------------------       Get Photo    -------------------------------------------------- */    $stmt2 = $conn->prepare("SELECT pic1 FROM photos WHERE cust_id = ?");    $stmt2->bind_param("i", $profid);    $stmt2->execute();    $photo = $stmt2->get_result()->fetch_assoc();    $stmt2->close();    $pic = $photo['pic1'] ?? "";    $pic11 = "profile/$profid/" . $pic;    if ($count == 1) {        echo '<div class="row text-center">';    }?>    <div class="col-md-3 col-sm-6">        <div class="team wow slideInLeft">            <div class="img-hexagon">                <?php                echo "<a target='_blank' href=\"view_profile.php?id={$profid}\">";                if (empty($pic)) {                    if ($row['sex'] === "Male") {                        echo "<img src='img/male.png' />";                    } else {                        echo "<img src='img/female.png' />";                    }                } else {                    echo "<img width='50px' height='50px' src='/$pic11' alt='' class='hover-animation image-zoom-in img-responsive' />";                }                ?>                <span class="img-top"></span>                <span class="img-bottom"></span>            </div>            <div class="team-content">                <?php                echo "<h4>{$row['firstname']} {$row['lastname']}</h4>";                echo "<p>{$row['age']} Yrs, {$row['religion']}</p>";                echo "<h5>View Full Profile</h5>";                echo "</a>";                ?>            </div>        </div>    </div><?php    if ($count >= 4) {        $count = 1;        $count2++;        echo "</div>";    } else {        $count++;        $count2++;    }    if ($count2 > 8) {        break;    }}$stmt->close();?>					       		</div><!-- Team end -->	</div><!-- 2nd container end --></section><!--/ Main container end -->	<?php include_once("includes/footer.php"); ?><?php include_once("includes/copyright.php"); ?>			</div><!-- Body inner end --><!-- jQuery --><script src="plugins/jQuery/jquery.min.js"></script><!-- Bootstrap JS --><script src="plugins/bootstrap/bootstrap.min.js"></script><!-- Style Switcher --><script type="text/javascript" src="plugins/style-switcher.js"></script><!-- Owl Carousel --><script type="text/javascript" src="plugins/owl/owl.carousel.js"></script><!-- PrettyPhoto --><script type="text/javascript" src="plugins/jquery.prettyPhoto.js"></script><!-- Bxslider --><script type="text/javascript" src="plugins/flex-slider/jquery.flexslider.js"></script><!-- Slick slider --><script type="text/javascript" src="plugins/slick/slick.min.js"></script><!-- Isotope --><script type="text/javascript" src="plugins/isotope.js"></script><script type="text/javascript" src="plugins/ini.isotope.js"></script><!-- Wow Animation --><script type="text/javascript" src="plugins/wow.min.js"></script><!-- Eeasing --><script type="text/javascript" src="plugins/jquery.easing.1.3.js"></script><!-- Counter --><script type="text/javascript" src="plugins/jquery.counterup.min.js"></script><!-- Waypoints --><script type="text/javascript" src="plugins/waypoints.min.js"></script><!-- google map --><script src="https://maps.googleapis.com/maps/api/js?key=AIzaSyCcABaamniA6OL5YvYSpB3pFMNrXwXnLwU&libraries=places"></script><script sr